/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic       clk,
    input  logic       in,
    input  logic       reset,
    output logic [7:0] out_byte,
    output logic       done
);
    typedef enum logic [1:0] {IDLE, DATA, STOP, RECOVER} state_t;
    state_t state_r;
    logic [2:0] bit_index_r;
    logic [7:0] data_r;

    always_ff @(posedge clk) begin
        if (reset) begin
            state_r     <= IDLE;
            bit_index_r <= 3'd0;
            data_r      <= 8'd0;
            out_byte    <= 8'd0;
            done        <= 1'b0;
        end else begin
            done <= 1'b0;
            case (state_r)
                IDLE: begin
                    if ("'!in) begin
                        state_r     <= DATA;
                        bit_index_r <= 3'"'d0;
                    end
                end
                DATA: begin
                    data_r[bit_index_r] <= in;
                    if (bit_index_r == 3'd7)
                        state_r <= STOP;
                    else
                        bit_index_r <= bit_index_r + 3'd1;
                end
                STOP: begin
                    if (in) begin
                        out_byte <= data_r;
                        done     <= 1'b1;
                        state_r  <= IDLE;
                    end else begin
                        state_r <= RECOVER;
                    end
                end
                RECOVER: begin
                    if (in)
                        state_r <= IDLE;
                end
                default: begin
                    state_r     <= IDLE;
                    bit_index_r <= 3'd0;
                end
            endcase
        end
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic in = 1;
    logic reset = 0;
    wire [7:0] out_byte;
    wire done;
    TopModule dut (.clk(clk), .in(in), .reset(reset), .out_byte(out_byte), .done(done));
    always #5 clk = ~clk;

    integer phase = -1; // -1 idle, 0..7 data, 8 stop, 9 recovery
    logic [7:0] expected_byte = 0;
    logic expected_done;
    integer samples = 0;
    integer completions = 0;
    integer i, j;
    logic [31:0] rng = 32'"'h7259ab13;

    task automatic tick(input logic bit_value, input logic rst_value);
        @(negedge clk);
        in = bit_value;
        reset = rst_value;
        @(posedge clk);
        expected_done = 0;
        if (rst_value) begin
            phase = -1;
            expected_byte = 0;
        end else if (phase == -1) begin
            if ("'!bit_value) phase = 0;
        end else if (phase < 8) begin
            expected_byte[phase] = bit_value;
            phase = phase + 1;
        end else if (phase == 8) begin
            if (bit_value) begin
                expected_done = 1;
                phase = -1;
            end else phase = 9;
        end else if (bit_value) phase = -1;
        #1;
        samples = samples + 1;
        if (done !== expected_done)
            $fatal(1, "done mismatch sample %0d phase %0d actual %b expected %b", samples, phase, done, expected_done);
        if (expected_done) begin
            completions = completions + 1;
            if (out_byte !== expected_byte)
                $fatal(1, "byte mismatch sample %0d actual %h expected %h", samples, out_byte, expected_byte);
        end
    endtask

    task automatic frame(input logic [7:0] payload, input logic stop_bit);
        integer k;
        tick(0,0);
        for (k=0; k<8; k=k+1) tick(payload[k],0);
        tick(stop_bit,0);
    endtask

    initial begin
        tick(1,1);
        repeat (12) tick(1,0);
        for (i=0; i<256; i=i+1) frame(i[7:0],1);
        frame(8'"'ha5,0);
        repeat (20) tick(0,0);
        tick(1,0);
        frame(8'h96,1);
        // Reset after every possible prefix, including stop/recovery phase.
        for (i=0; i<=10; i=i+1) begin
            tick(1,1);
            tick(0,0);
            for (j=0; j<i; j=j+1) tick(0,0);
            tick(0,1);
            tick(1,0);
            frame(8'h81,1);
        end
        // Synchronous reset has no effect between rising edges.
        frame(8'h42,1);
        @(negedge clk);
        reset = 1;
        #1;
        if (done "'!== 1 || out_byte !== 8'"'h42)
            "'$fatal(1, "reset acted asynchronously");
        reset = 0;
        tick(1,0);
        for (i=0; i<12000; i=i+1) begin
            rng = rng ''^ (rng << 13);
            rng = rng ''^ (rng >> 17);
            rng = rng ''^ (rng << 5);
            tick(rng[0], rng[9:4] == 0);
        end
        tick(1,1);
        frame(8'"'hff,1);
        "'$display("PASS: %0d samples checked, %0d valid frames", samples, completions);
        $finish;
    end
    initial begin
        #300000;
        $fatal(1, "testbench timeout");
    end
endmodule
EOF
timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile_initial.log 2>&1
compile_status=$?
cat compile_initial.log
printf '"'compile_exit=%s\\n' \""'$compile_status"
if [ "$compile_status" -eq 0 ]; then
 timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation_initial.log 2>&1
 simulation_status=$?
 cat simulation_initial.log
 printf '"'simulation_exit=%s\\n' \""'$simulation_status"
fi'

